        self.rows=[]
        self.notes={}
        self.loading=False
        self.error=None
        self.seq=0
        self.request_in_progress=None
    def begin(self, query):
        self.seq+=1
        self.request_in_progress=self.seq
        self.error=None
        return self.seq
    def finish(self, request_id, rows):
        if self.request_in_progress is None:
            return False
        if self.request_in_progress != request_id:
            return False
        if self.rows:
            return False
        self.request_in_progress=None
        self.rows=rows
        self.loading=True
        return True

